INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('tag-der-offenen-tuer-parlament-nationalfeiertag-2026','Tag der offenen Tür im Parlament: Programm am Nationalfeiertag 2026','Am 26. Oktober öffnet das Parlament von 10 bis 16 Uhr: Rundgang durch die Plenarsäle, Gespräche mit Abgeordneten und Programm für Kinder. Alle Infos zum Besuch.','Der **Tag der offenen Tür im Parlament** findet am Nationalfeiertag, Montag, 26. Oktober 2026, statt: Von 10 bis 16 Uhr öffnet das Hohe Haus an der Wiener Ringstraße seine Türen für alle Interessierten. Der Eintritt ist laut Parlamentsdirektion ohne Anmeldung möglich, wer Wartezeiten vermeiden will, reserviert vorab online ein Zeitfenster.

Der Termin hat Tradition: Am 26. Oktober 1955 beschloss der Nationalrat das Bundesverfassungsgesetz über die immerwährende Neutralität Österreichs. Seither ist der Tag Nationalfeiertag, und das Parlament nutzt ihn, um Bürgerinnen und Bürgern Einblick in die Arbeit der Abgeordneten zu geben.

## Programm beim Tag der offenen Tür im Parlament

Im Mittelpunkt steht ein rund 45-minütiger Rundgang durch das Gebäude. Besucherinnen und Besucher sehen dabei die Plenarsäle von Nationalrat und Bundesrat sowie den historischen Sitzungssaal, in dem die Bundesversammlung zusammentritt. Laut aktueller Parlamentskorrespondenz ist zusätzlich ein Ausschusslokal zugänglich, das sonst nicht für die Öffentlichkeit geöffnet ist.

Weitere Programmpunkte:

- **Säulenhalle:** Abgeordnete aller fünf Parlamentsklubs – FPÖ, ÖVP, SPÖ, NEOS und Grüne – stehen an Informationsständen für Gespräche bereit.
- **Empfangssalon:** Hier können Gäste das Präsidium des Nationalrats sowie die Präsidentin des Bundesrats treffen.
- **Abschluss über die Rampe:** Der Rundgang endet über die Parlamentsrampe, die sonst Staatsgästen vorbehalten ist, mit Blick über die Ringstraße.

## Angebote für Kinder und Familien

Für jüngere Gäste gibt es einen Stickerpass, ein Quiz und eine Malstation. Am Ende des Besuchs warten die Parlamentsmaskottchen auf ein „High Five“. Das Parlament bewirbt den Tag damit ausdrücklich auch als Ausflug für Familien.

## Barrierefreiheit und Sprachen

Alle Angebote sind barrierefrei. Die Führungen werden auf Deutsch, Englisch und in Österreichischer Gebärdensprache angeboten. Für Fragen ist das Parlament telefonisch unter +43 1 401 10-0 sowie per E-Mail an info@parlament.gv.at erreichbar.

## So kommen Sie hin: Adresse und Tipps

Das Parlament befindet sich am Dr.-Karl-Renner-Ring 3 im ersten Wiener Gemeindebezirk. Die erste Gruppe wird kurz vor 10 Uhr eingelassen, der letzte Einlass richtet sich nach dem Ende der Veranstaltung um 16 Uhr. Wer spontan kommt, muss mit längeren Wartezeiten rechnen – am Nationalfeiertag ist in der Wiener Innenstadt traditionell viel los, da auch andere Einrichtungen im Regierungsviertel Programm anbieten.

Praktische Hinweise für den Besuch:

1. Zeitfenster vorab über die Veranstaltungsseite des Parlaments buchen.
2. Früh anreisen, vor allem am Vormittag ist der Andrang erfahrungsgemäß groß.
3. Mit öffentlichen Verkehrsmitteln anreisen, etwa mit der U-Bahn-Linie U2 (Station Volkstheater oder Rathaus) oder den Straßenbahnlinien am Ring.

## Präsidium eröffnet den Tag

Vor dem Publikumsstart begrüßen Nationalratspräsident Walter Rosenkranz, der Zweite Nationalratspräsident Peter Haubner, Bundesratspräsidentin Christine Schwarz-Fuchs und Parlamentsdirektor Roland Weinert um 9.50 Uhr in der Agora. Am Abend nehmen Vertreterinnen und Vertreter des Bundesrats an einer Marienfeier im Stephansdom teil.

Auch die restliche Parlamentswoche ist von Terminen außerhalb des Plenarbetriebs geprägt: Am Freitag, 30. Oktober, diskutieren Jugendvertrauensräte der Gewerkschaftsjugend im Nationalratssaal mit Abgeordneten über Demokratie und Mitbestimmung junger Menschen. Zu Allerheiligen besuchen Nationalratspräsident und Parlamentsdirektor die Gräber früherer Nationalratspräsidenten am Wiener Zentralfriedhof.

Wer den Termin am Nationalfeiertag verpasst, kann das Parlament auch an anderen Tagen im Rahmen regulärer Führungen besichtigen oder eine Plenarsitzung von der Galerie aus verfolgen.','politik','Parlament','wien','news','Presseinfo Redaktion','/assets/img/artikel/tag-der-offenen-tuer-parlament-nationalfeiertag-2026.webp','Parlament Österreich (Parlamentskorrespondenz)','https://www.parlament.gv.at/aktuelles/news/Tag-der-offenen-Tuer-am-26.-Oktober-im-Hohen-Haus','published','2026-10-25T05:45:00.000Z','2026-10-25T05:44:26.711Z','Tag der offenen Tür Parlament 2026: Zeiten & Programm','Tag der offenen Tür im Parlament am 26. Oktober 2026: Öffnungszeiten, Führungen, Kinderprogramm und Tipps für den Besuch am Nationalfeiertag in Wien.','Tag der offenen Tür Parlament','["Tag der offenen Tür Parlament","Nationalfeiertag 2026","Parlament Wien","Nationalfeiertag Wien Programm","Parlament Führung Nationalfeiertag","26. Oktober Wien","Hohes Haus besuchen","Nationalfeiertag mit Kindern Wien"]','Tag der offenen Tür im Parlament: Besucher in der Säulenhalle des Hohen Hauses in Wien','Wide view of the grand neoclassical columned hall of the Austrian Parliament building in Vienna on an autumn open day, visitors from behind walking between marble columns, warm daylight through skylight, families, no text, no logos, no readable signs','[{"q":"Wann ist der Tag der offenen Tür im Parlament 2026?","a":"Am Nationalfeiertag, Montag, 26. Oktober 2026, von 10 bis 16 Uhr im Parlament am Dr.-Karl-Renner-Ring 3 in Wien."},{"q":"Muss man sich anmelden?","a":"Nein, spontane Besuche sind möglich. Wer längere Wartezeiten vermeiden möchte, bucht online ein Zeitfenster."},{"q":"Ist der Besuch barrierefrei?","a":"Ja, alle Angebote sind barrierefrei, Führungen gibt es auf Deutsch, Englisch und in Österreichischer Gebärdensprache."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.reg